const body = $input.first().json.body || $input.first().json;
const message = body.message || '';
const ticketId = body.ticketId || Date.now();
const customerName = body.customerName || 'Customer';
const customerEmail = body.customerEmail || '';
const platform = body.platform || 'shopify';
const orderId = body.orderId || null;

// Input validation
if (!message || message.trim().length === 0) {
  throw new Error(`Invalid input: message is required. Received ticketId=${ticketId}`);
}

// Force-error mode for testing: pass through to trigger downstream AI Agent failure
const forceError = String(ticketId).startsWith('test-force-error-');

const startTime = Date.now();

return [{
  json: {
    startTime,
    ticketId,
    customerName,
    customerEmail,
    platform,
    orderId,
    chatInput: 'Platform: ' + platform + '\nMessage: ' + message + '\nOrder ID: ' + (orderId || 'None'),
    forceError
  }
}];

const agentOutput = $input.first().json.output || $input.first().json.text || '{}';
let parsed;
try {
  // 先去掉 markdown code fence，再把未转义的实际换行符转义（reply 字段里常见）
  const cleaned = agentOutput
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```\s*$/i, '')
    .trim();
  const match = cleaned.match(/\{[\s\S]*\}/);
  const jsonStr = match ? match[0] : cleaned;
  // 把 JSON 字符串值中的实际换行符转义，避免 parse 失败
  const safeStr = jsonStr.replace(/("(?:[^"\\]|\\.)*")|(\n)/g, (m, quoted, newline) => {
    if (quoted) return quoted; // 保留字符串内的已转义内容
    return '\\n';             // 字符串外的裸换行忽略（通常不存在）
  });
  // 更稳健：先尝试直接 parse，失败再用 replace 清理后重试
  try {
    parsed = JSON.parse(jsonStr);
  } catch {
    // 把字符串值内的裸换行和 tab 转义
    const fixed = jsonStr.replace(/"((?:[^"\\]|\\.)*)"/g, (m, inner) => {
      return '"' + inner.replace(/\n/g, '\\n').replace(/\r/g, '\\r').replace(/\t/g, '\\t') + '"';
    });
    parsed = JSON.parse(fixed);
  }
} catch (parseError) {
  // 最后尝试：用正则从原始输出中提取 classification 字段值
  const classMatch = agentOutput.match(/"classification"\s*:\s*"(auto|draft|escalate)"/i);
  const replyMatch = agentOutput.match(/"reply"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  const reasonMatch = agentOutput.match(/"reason"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  const riskMatch = agentOutput.match(/"risk_level"\s*:\s*"(low|medium|high)"/i);
  if (classMatch) {
    parsed = {
      classification: classMatch[1],
      reason: reasonMatch ? reasonMatch[1] : 'Extracted from malformed JSON',
      risk_level: riskMatch ? riskMatch[1] : 'medium',
      reply: replyMatch ? replyMatch[1] : null
    };
  } else {
    parsed = { classification: 'escalate', reason: 'AI output parse error', risk_level: 'high', reply: null };
  }
}

const ticket = $('Parse Input').first().json;
const classification = parsed.classification || 'escalate';

if (!['auto', 'draft', 'escalate'].includes(classification)) {
  parsed.classification = 'escalate';
  parsed.reason = 'Invalid classification: ' + classification;
}

let status;
if (classification === 'auto') status = 'auto_replied';
else if (classification === 'draft') status = 'needs_review';
else status = 'escalated';

const aiCallTimeMs = Date.now() - ticket.startTime;

return [{
  json: {
    aiCallTimeMs,
    status,
    classification: parsed.classification,
    reason: parsed.reason || '',
    riskLevel: parsed.risk_level || 'high',
    reply: parsed.reply || null,
    ticketId: ticket.ticketId,
    customerName: ticket.customerName,
    customerEmail: ticket.customerEmail,
    platform: ticket.platform,
    originalMessage: ticket.chatInput
  }
}];

const ticket = $('Parse Input').first().json;
const error = $input.first().json.error || {};

// 降级兜底逻辑：AI 失败时标记为 draft（需人工审核）而非 escalate
// 这是更安全的选择，避免误判为高风险
const aiCallTimeMs = Date.now() - ticket.startTime;

// Capture n8n execution context
const executionId = $execution.id;
const workflowId = $workflow.id;
const workflowName = $workflow.name;
const failedNode = error.node?.name || 'AI Agent';

return [{
  json: {
    aiCallTimeMs,
    status: 'needs_review',
    classification: 'draft',
    reason: 'AI 分类服务暂时不可用，已标记为待审核: ' + (error.message || 'Unknown error'),
    riskLevel: 'medium',
    reply: '感谢您的消息。我们的团队会尽快为您处理。',
    ticketId: ticket.ticketId,
    customerName: ticket.customerName,
    customerEmail: ticket.customerEmail,
    platform: ticket.platform,
    originalMessage: ticket.chatInput,
    errorDetails: JSON.stringify(error),
    fallbackApplied: true,
    n8nExecutionId: executionId,
    n8nWorkflowId: workflowId,
    n8nWorkflowName: workflowName,
    failedNode: failedNode
  }
}];
